background-image: url('/images/browsers-sprite.png[]');
background-repeat: no-repeat;
height: 128px;
width: 128px;
}
.icon-facebook {
background-position: 0px 0px;
}
.icon-twitter {
background-position: 0px -128px;
}
.icon-linkedin {
background-position: 0px -256px;
}
