quality: 75,
progressive: true,
tune: 'ms-ssim'
})]
}))
.pipe(gulp.dest('images/derivative/' + sizes[size] + '/'))
.pipe(webp({
quality: 75
})())
.pipe(gulp.dest('images/derivative/' + sizes[size] + '/'))
}
return stream;
});
